// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address a1, address a2, uint128 v1, uint128 v2, uint8 n) public {
        vm.assume(a1 != address(0));
        vm.assume(a2 != address(0));
        uint256 len = n == 0 ? 1 : 2;
        address[] memory tos = new address[](len);
        uint256[] memory vs = new uint256[](len);
        tos[0] = a1;
        vs[0] = uint256(v1);
        if (len == 2) {
            tos[1] = a2;
            vs[1] = uint256(v2);
        }
        vm.prank(owner);
        bool ok = c.transfer(tos, vs);
        // Rule: any transfer() that does not revert must report success (return true).
        assertTrue(ok);
    }
}
